namespace AccessControl;

public sealed class AccessDecisionEngine
{
    public AccessDecision Decide(Principal? principal, Resource? resource, AccessRequest? request, IDelegationRegister delegations)
    {
        if (TryGetContextFailure(principal, resource, request, out var failure))
            return failure;

        return DecideWithValidContext(principal!, resource!, request!, delegations);
    }

    private static bool TryGetContextFailure(
        Principal? principal,
        Resource? resource,
        AccessRequest? request,
        out AccessDecision failure)
    {
        if (principal is null || resource is null || request is null)
            return Fail("missing-context", out failure);
        if (string.IsNullOrWhiteSpace(principal.Id) || string.IsNullOrWhiteSpace(resource.Id))
            return Fail("invalid-identity", out failure);
        if (principal.Suspended)
            return Fail("principal-suspended", out failure);
        if (!string.Equals(principal.TenantId, resource.TenantId, StringComparison.Ordinal))
            return Fail("tenant-mismatch", out failure);
        if (resource.Locked && request.Action != "read")
            return Fail("resource-locked", out failure);
        if (request.MinuteOfDay is < 0 or > 1439)
            return Fail("invalid-time", out failure);
        if (principal.FailedChallenges >= 3 && !request.StrongAuthentication)
            return Fail("challenge-required", out failure);

        failure = default!;
        return false;
    }

    private static AccessDecision DecideWithValidContext(
        Principal principal,
        Resource resource,
        AccessRequest request,
        IDelegationRegister delegations)
    {
        var facts = new AuthorizationFacts(
            principal.Roles.Contains("administrator"),
            principal.Roles.Contains("operator"),
            principal.Roles.Contains("auditor"),
            principal.Id == resource.OwnerId,
            delegations.HasDelegation(principal.Id, resource.Id, request.Action));

        if (TryGetSecurityDecision(resource, request, facts, out var securityDecision))
            return securityDecision;
        if (TryGetActionFailure(request.Action, facts, out var actionFailure))
            return actionFailure;

        var outsideBusinessHours = request.MinuteOfDay < 480 || request.MinuteOfDay > 1080;
        return new AccessDecision(
            true,
            facts.Delegated ? "delegated" : "role-or-ownership",
            outsideBusinessHours || resource.Classification == "restricted");
    }

    private static bool TryGetSecurityDecision(
        Resource resource,
        AccessRequest request,
        AuthorizationFacts facts,
        out AccessDecision decision)
    {
        if (request.BreakGlass)
        {
            decision = !facts.Administrator || !request.StrongAuthentication
                ? new AccessDecision(false, "invalid-break-glass", true)
                : new AccessDecision(true, "break-glass", true);
            return true;
        }

        if (resource.Classification == "restricted" && !request.StrongAuthentication)
            return Fail("strong-authentication-required", out decision);
        if (resource.Classification == "restricted" && request.NetworkZone != "trusted")
            return Fail("trusted-network-required", out decision);

        decision = default!;
        return false;
    }

    private static bool TryGetActionFailure(
        string action,
        AuthorizationFacts facts,
        out AccessDecision failure)
    {
        if (action == "delete" && !facts.Administrator)
            return Fail("administrator-required", out failure);
        if (action == "write" && !(facts.Administrator || facts.Operator || facts.Owner || facts.Delegated))
            return Fail("write-not-authorised", out failure);
        if (action == "read" && !(facts.Administrator || facts.Operator || facts.Auditor || facts.Owner || facts.Delegated))
        {
            failure = new AccessDecision(false, "read-not-authorised", false);
            return true;
        }
        if (action is not ("read" or "write" or "delete"))
            return Fail("unknown-action", out failure);

        failure = default!;
        return false;
    }

    private static bool Fail(string reason, out AccessDecision failure)
    {
        failure = new AccessDecision(false, reason, true);
        return true;
    }

    private readonly struct AuthorizationFacts
    {
        public AuthorizationFacts(bool administrator, bool operatorRole, bool auditor, bool owner, bool delegated)
        {
            Administrator = administrator;
            Operator = operatorRole;
            Auditor = auditor;
            Owner = owner;
            Delegated = delegated;
        }

        public bool Administrator { get; }
        public bool Operator { get; }
        public bool Auditor { get; }
        public bool Owner { get; }
        public bool Delegated { get; }
    }
}
